<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>동전 먹기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fefce8; color: #1f2937; padding: 24px; }
    canvas { background: #ecfccb; border: 3px solid #ca8a04; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🪙 동전 먹기 (💣 조심!)</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="420" height="420"></canvas>
  <p id="msg">방향키로 움직여 동전을 먹어요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let player = { x: 200, y: 200, r: 14 };
    let coin = { x: 60, y: 60, r: 10 };
    let bombs = [];   // { x, y, r, dx, dy }
    let keys = {};
    let score = 0;
    let lives = 3;
    let safeTime = 0;
    let running = false;
    let timer = null;

    function touch(a, b) {
      return Math.hypot(a.x - b.x, a.y - b.y) < a.r + b.r;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function placeCoin() {
      coin.x = 20 + Math.random() * (W - 40);
      coin.y = 20 + Math.random() * (H - 40);
    }

    function addBomb() {
      // 플레이어 가까이에서는 생기지 않게 구석에서 출발
      bombs.push({ x: 20, y: 20 + Math.random() * (H - 40), r: 12, dx: 2 + Math.random() * 1.5, dy: 2 - Math.random() * 4 });
    }

    function startGame() {
      clearInterval(timer);
      player.x = 200; player.y = 200;
      bombs = [];
      addBomb();
      placeCoin();
      keys = {};
      score = 0;
      lives = 3;
      safeTime = 0;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function tick() {
      if (!running) return;
      if (keys.ArrowLeft) player.x = Math.max(player.r, player.x - 4);
      if (keys.ArrowRight) player.x = Math.min(W - player.r, player.x + 4);
      if (keys.ArrowUp) player.y = Math.max(player.r, player.y - 4);
      if (keys.ArrowDown) player.y = Math.min(H - player.r, player.y + 4);

      for (const b of bombs) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < b.r || b.x > W - b.r) b.dx = -b.dx;
        if (b.y < b.r || b.y > H - b.r) b.dy = -b.dy;
      }

      if (touch(player, coin)) {
        score += 1;
        updateInfo();
        placeCoin();
        if (score % 5 === 0) addBomb(); // 5개마다 폭탄 추가
      }

      if (safeTime > 0) {
        safeTime -= 1;
      } else if (bombs.some(function (b) { return touch(player, b); })) {
        lives = Math.max(0, lives - 1);
        safeTime = 50;
        updateInfo();
        if (lives === 0) gameOver();
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🪙', coin.x, coin.y);
      bombs.forEach(function (b) { ctx.fillText('💣', b.x, b.y); });
      if (safeTime % 10 < 5) ctx.fillText('😀', player.x, player.y);
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
