  <title>라면 45초 타이머</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ede9fe; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>라면 45초 타이머</h1>
  <p id="time" style="font-size: 64px">45</p>
  <button id="start">시작</button>
  <button id="reset">처음으로</button>
  <p id="msg"></p>
  <script>
    const total = 45;
    let left = total;
    let timerId = null;
    const timeEl = document.getElementById('time');
    const msg = document.getElementById('msg');

    function stop() {
      clearInterval(timerId);
      timerId = null;
    }

    document.getElementById('start').addEventListener('click', function () {
      if (timerId) return;
      msg.textContent = '';
      if (left <= 0) left = total;
      timerId = setInterval(function () {
        left -= 1;
        timeEl.textContent = left;
