<body>
  <h1 id="title">방향키 게임</h1>
  <h1 id="arrowTx">⬆</h1>
  <h3 id="scoreTx">화면에 나온 화살표 키를 누르세요!</h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var k, arrows, want, score;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function press(k) {
      if (k == want) {
        score = (typeof score === 'number' ? score : 0) + 1;
      } else {
        score = 0;
      }
      document.getElementById("scoreTx").textContent = score;
      want = mathRandomInt(1, 4);
      document.getElementById("arrowTx").textContent = arrows[(want - 1)];
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        press(1);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        press(2);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        press(3);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        press(4);
      }
    });

    arrows = ['⬆', '⬇', '⬅', '➡'];
    want = 1;
    score = 0;
    __size("arrowTx", "fontSize", 90);
  </script>
