      var o = __audio.createOscillator(), g = __audio.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, t);
      if (to) o.frequency.exponentialRampToValueAtTime(to, t + sec);
      g.gain.setValueAtTime(vol, t);
      if (hold) g.gain.setValueAtTime(vol, t + sec * hold);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.connect(g); g.connect(__snd());
      o.start(t); o.stop(t + sec + 0.02);
    }
    function __sfx(k) {
      __snd();
      var t = __audio.currentTime;
      if (k === 'coin') { __tone(988, t, 0.08, 'square', 0.1); __tone(1319, t + 0.08, 0.3, 'square', 0.1); }
      else if (k === 'jump') __tone(260, t, 0.25, 'square', 0.1, 820);
      else if (k === 'laser') __tone(1500, t, 0.22, 'sawtooth', 0.08, 120);
      else if (k === 'pop') __tone(500, t, 0.09, 'sine', 0.3, 1100);
      else if (k === 'win') [523.25, 659.25, 783.99, 1046.5].forEach(function (f, i) { __tone(f, t + i * 0.1, 0.3, 'triangle', 0.22); });
      else if (k === 'lose') [392, 349.23, 311.13, 261.63].forEach(function (f, i) { __tone(f, t + i * 0.18, 0.3, 'sawtooth', 0.08, 0, 0.6); });
