      // Take the top task and move it to done
      if (!todos.length) {
        document.getElementById("Alerts").textContent = '🙌 Nothing left to do';
      } else {
        doneItems.push(todos.shift());
        document.getElementById("Alerts").textContent = '👍 Well done!';
        __sfx("coin");
        show_lists();
      }
    });
    document.getElementById("clearAll").addEventListener('click', function () {
      todos = [];
      doneItems = [];
      document.getElementById("Alerts").textContent = 'All cleared';
      show_lists();
    });

    // Start with two empty lists
    todos = [];
    doneItems = [];
    show_lists();
