  <title>튕기는 공</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #111827; color: #f9fafb; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    canvas { background: #1f2937; border: 3px solid #94a3b8; border-radius: 8px; }
  </style>
</head>
<body>
  <h1>튕기는 공</h1>
  <canvas id="canvas" width="480" height="320"></canvas>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const balls = [];

    function addBall() {
      balls.push({
        x: Math.random() * (canvas.width - 28) + 14,
        y: Math.random() * (canvas.height - 28) + 14,
        dx: (Math.random() < 0.5 ? -1 : 1) * 7,
        dy: (Math.random() < 0.5 ? -1 : 1) * 7
      });
    }

    for (let i = 0; i < 3; i++) {
      addBall();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      balls.forEach(function (b) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < 14 || b.x > canvas.width - 14) b.dx = -b.dx;
        if (b.y < 14 || b.y > canvas.height - 14) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 14, 0, Math.PI * 2);
        ctx.fillStyle = '#ef4444';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
  </script>
</body>
</html>
