      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newQ() {
      a = mathRandomInt(2, 9);
      b = mathRandomInt(2, 9);
      document.getElementById("q").textContent = [a,' × ',b,' = ?'].join('');
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (i <= 10) {
          if ((parseFloat(document.getElementById("ans").value) || 0) == a * b) {
            s = (typeof s === 'number' ? s : 0) + 1;
          }
          document.getElementById("ans").value = '';
          i = (typeof i === 'number' ? i : 0) + 1;
          if (i > 10) {
