  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var i;

    document.getElementById("txt").addEventListener('input', function () {
      document.getElementById("out").textContent = '';
      var i_start = document.getElementById("txt").value.length;
      var i_inc = 1;
      if (i_start > 1) {
        i_inc = -i_inc;
      }
      for (i = i_start; i_inc >= 0 ? i <= 1 : i >= 1; i += i_inc) {
        __add("out", document.getElementById("txt").value.charAt((i - 1)));
      }
    });
  </script>
