      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n;

    document.getElementById("addB").addEventListener('click', function () {
      if (!!document.getElementById("item").value.trim().length) {
        __add("items", document.getElementById("item").value);
        n = (typeof n === 'number' ? n : 0) + 1;
        document.getElementById("cnt").textContent = String(n) + ' items';
        document.getElementById("item").value = '';
      }
    });
    document.getElementById("clearB").addEventListener('click', function () {
      document.getElementById("items").textContent = '';
      n = 0;
      document.getElementById("cnt").textContent = '0 items';
    });

    n = 0;
