    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h1 id="prob">⚡ 구구단 30초! 시작을 눌러</h1>
  <input id="ans" type="number" placeholder="답 쓰고 엔터">
  <button id="go">시작</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var score, a, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newQ() {
      a = mathRandomInt(2, 9);
      b = mathRandomInt(2, 9);
      document.getElementById("prob").textContent = [a,' × ',b].join('');
      document.getElementById("ans").value = '';
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      __show("go", "hide");
      __show("ans", "show");
      newQ();
      setTimeout(function () {
        __show("ans", "hide");
        __show("go", "show");
        document.getElementById("prob").textContent = ['끝! ',score,'개 맞혔어'].join('');
      }, (30) * 1000);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if ((parseFloat(document.getElementById("ans").value) || 0) == a * b) {
          score = (typeof score === 'number' ? score : 0) + 1;
          __beep(523.25, 0.05);
          newQ();
        } else {
          document.getElementById("ans").value = '';
        }
      }
    });

    __show("ans", "hide");
  </script>
</body>
</html>
