<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>타자 연습</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f0f9ff; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 24px; padding: 8px; margin: 4px; width: 260px; text-align: center; }
    #word { font-size: 44px; font-weight: bold; color: #0369a1; min-height: 56px; }
    #msg { font-size: 22px; font-weight: bold; min-height: 28px; }
  </style>
</head>
<body>
  <h1>⌨️ 타자 연습 1분</h1>
  <p>맞힌 단어: <span id="score">0</span> · 남은 시간: <span id="time">60</span>초</p>
  <div id="word">준비</div>
  <input id="typing" placeholder="여기에 입력" disabled>
  <p id="msg"></p>
  <button id="start">시작</button>
  <script>
    const words = ['사과', '바나나', '고양이', '강아지', '학교', '친구', '컴퓨터', '하늘', '바다', '무지개',
      '자전거', '도서관', '우주선', '연필', '선생님', '축구공', '아이스크림', '피아노', '눈사람', '해바라기'];
    const input = document.getElementById('typing');
    const wordEl = document.getElementById('word');
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');
    let current = '';
    let score = 0;
    let timeLeft = 60;
    let running = false;
    let timer = null;

    function nextWord() {
      let w = current;
      while (w === current) w = words[Math.floor(Math.random() * words.length)];
      current = w;
      wordEl.textContent = current;
    }

    function startGame() {
      clearInterval(timer);
      score = 0;
      timeLeft = 60;
      running = true;
      document.getElementById('score').textContent = 0;
      document.getElementById('time').textContent = 60;
      msg.textContent = '';
      input.disabled = false;
      input.value = '';
      input.focus();
      startBtn.textContent = '다시 시작';
      nextWord();
      timer = setInterval(function () {
        if (!running) return;
        timeLeft -= 1;
        document.getElementById('time').textContent = timeLeft;
        if (timeLeft <= 0) endGame();
      }, 1000);
    }

    function endGame() {
      running = false;
      clearInterval(timer);
      timeLeft = 0;
      document.getElementById('time').textContent = 0;
      input.disabled = true;
      wordEl.textContent = '끝!';
      msg.textContent = '⏰ 게임 끝! 1분 동안 ' + score + '개 맞혔어요';
    }

