      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var step;

    document.getElementById("next").addEventListener('click', function () {
      step = (step + 1) % 3;
      if (step == 0) {
        document.getElementById("light").style.color = "#ef4444";
        document.getElementById("label").textContent = 'Red';
      } else if (step == 1) {
        document.getElementById("light").style.color = "#facc15";
        document.getElementById("label").textContent = 'Yellow';
      } else {
        document.getElementById("light").style.color = "#22c55e";
        document.getElementById("label").textContent = 'Green';
      }
    });

    step = 0;
    __size("light", "fontSize", 120);
