    <button id="sc">✌️</button>
    <button id="p">✋</button>
  </div>
  <p id="res">골라 보세요</p>
  <p id="board">이김 0 / 짐 0 / 비김 0</p>
  <script>
    var me, win, d, lose, tie;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function play(me) {
      d = ((me - mathRandomInt(1, 3)) + 3) % 3;
      if (d == 0) {
        tie = (typeof tie === 'number' ? tie : 0) + 1;
        document.getElementById("res").textContent = '비겼어요';
      } else if (d == 1) {
        win = (typeof win === 'number' ? win : 0) + 1;
        document.getElementById("res").textContent = '이겼어요!';
      } else {
        lose = (typeof lose === 'number' ? lose : 0) + 1;
        document.getElementById("res").textContent = '졌어요';
      }
      document.getElementById("board").textContent = ['이김 ',win,' / 짐 ',lose,' / 비김 ',tie].join('');
    }

    document.getElementById("r").addEventListener('click', function () {
      play(1);
    });
    document.getElementById("sc").addEventListener('click', function () {
      play(2);
    });
    document.getElementById("p").addEventListener('click', function () {
      play(3);
    });

    win = 0;
    lose = 0;
    tie = 0;
  </script>
</body>
</html>
