    });
    document.addEventListener('keydown', function (e) {
      if (e.key === " ") {
        e.preventDefault();
        cnt = (typeof cnt === 'number' ? cnt : 0) + 1;
        document.getElementById("n").textContent = cnt;
        if (cnt == 100) {
          __beep(523.25, 0.4);
