  <h2 id="t">동전 10번 던지기</h2>
  <button id="go">던지기</button>
  <h1 id="out"></h1>
  <script>
    var heads;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      heads = 0;
      for (var count = 0; count < 10; count++) {
        if (mathRandomInt(1, 2) == 1) {
          heads = (typeof heads === 'number' ? heads : 0) + 1;
        }
      }
      document.getElementById("out").textContent = ['앞면 ',heads,'번, 뒷면 ',10 - heads,'번'].join('');
    });
  </script>
</body>
</html>
